package eval

func shopsSuite() Suite {
	base := settlementsSuite()
	shop := map[string]any{"shop_id": "shop-lionshield", "name": "Lionshield Coster", "stock": map[string]any{"healing-potion": 3}, "buy_price": 2, "sell_price": 1}
	return Suite{ID: "070-shops", Name: "Campaign Play 070: Shops", Tests: append(base.Tests,
		playTestExactJSON("play-shop-create-settlement", "DM creates a shop settlement by public REST", "POST", "/v1/play/campaigns/play-2/settlements", map[string]any{"settlement_id": "settle-phandalin-shops", "name": "Phandalin Shops", "services": []any{"market"}, "availability": "open"}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"settlement_id": "settle-phandalin-shops", "name": "Phandalin Shops", "services": []any{"market"}, "availability": "open", "discovered_by": []any{}}),
		playTest("play-shop-browse-before-discovery", "A player cannot browse shops before discovering the settlement", "GET", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield", nil, map[string]string{"Authorization": playerAAuth}, 404, nil),
		playTestExactJSON("play-shop-discover-settlement", "Player discovers the shop settlement by public REST", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/discover", nil, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"settlement_id": "settle-phandalin-shops", "name": "Phandalin Shops", "services": []any{"market"}, "availability": "open", "discovered_by": []any{"play-char-w"}}),
		playTest("play-shop-player-create-forbidden", "Players cannot create shops", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops", shop, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-shop-create-missing-settlement", "Shop creation requires an existing settlement", "POST", "/v1/play/campaigns/play-2/settlements/settle-missing/shops", shop, map[string]string{"Authorization": dmAuth}, 404, nil),
		playTest("play-shop-invalid-id", "Shop creation requires a nonempty shop ID", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops", map[string]any{"shop_id": "", "name": "Broken Shop", "stock": map[string]any{"healing-potion": 1}, "buy_price": 2, "sell_price": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-shop-invalid-stock-item", "Shop stock requires valid catalog item IDs", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops", map[string]any{"shop_id": "shop-bad-item", "name": "Bad Item", "stock": map[string]any{"longsword": 1}, "buy_price": 2, "sell_price": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-shop-invalid-stock-quantity", "Shop stock quantities must be positive integers", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops", map[string]any{"shop_id": "shop-bad-qty", "name": "Bad Quantity", "stock": map[string]any{"healing-potion": 0}, "buy_price": 2, "sell_price": 1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-shop-invalid-prices", "Shop prices must follow buy positive and sell nonnegative rules", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops", map[string]any{"shop_id": "shop-bad-price", "name": "Bad Price", "stock": map[string]any{"healing-potion": 1}, "buy_price": 0, "sell_price": -1}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-shop-create-lionshield", "DM creates a deterministic settlement shop", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops", shop, map[string]string{"Authorization": dmAuth}, 201, shop),
		playTest("play-shop-duplicate-id", "Duplicate shop IDs conflict per settlement", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops", shop, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-shop-browse-dm", "DM can browse shop stock", "GET", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield", nil, map[string]string{"Authorization": dmAuth}, 200, shop),
		playTestExactJSON("play-shop-browse-discovered-player", "A player can browse after discovering the settlement", "GET", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield", nil, map[string]string{"Authorization": playerAAuth}, 200, shop),
		playTest("play-shop-buy-dm-forbidden", "DM cannot buy from shops", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/buy", map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": dmAuth}, 403, nil),
		playTest("play-shop-buy-non-owner-forbidden", "Players cannot buy for another player's character", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/buy", map[string]any{"character_id": "play-char-b", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-shop-buy-invalid-item", "Buying validates item and quantity", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/buy", map[string]any{"character_id": "play-char-w", "item_id": "longsword", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTestExactJSON("play-shop-fund-wizard", "Public currency transfer restores deterministic shop funds", "POST", "/v1/play/campaigns/play-2/characters/play-char-b/currency/transfers", map[string]any{"to_character_id": "play-char-w", "gold": 3}, map[string]string{"Authorization": playerBAuth}, 201, map[string]any{"from_character_id": "play-char-b", "to_character_id": "play-char-w", "gold": 3, "from_gold": 10, "to_gold": 10, "transfer_id": 2}),
		playTestExactJSON("play-shop-buy-potion", "Player buys one stocked item with gold", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/buy", map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 1, "gold": 8, "stock": 2}),
		playTest("play-shop-buy-insufficient-stock", "Buying more than stock rejects without mutation", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/buy", map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 99}, map[string]string{"Authorization": playerAAuth}, 409, nil),
		playTestExactJSON("play-shop-drain-wizard-gold", "Public currency transfer sets up insufficient-funds rejection", "POST", "/v1/play/campaigns/play-2/characters/play-char-w/currency/transfers", map[string]any{"to_character_id": "play-char-b", "gold": 8}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"from_character_id": "play-char-w", "to_character_id": "play-char-b", "gold": 8, "from_gold": 0, "to_gold": 18, "transfer_id": 3}),
		playTest("play-shop-buy-insufficient-gold", "Buying beyond character gold rejects without mutation", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/buy", map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 409, nil),
		playTestExactJSON("play-shop-refund-wizard-gold", "Public currency transfer restores deterministic sell balance", "POST", "/v1/play/campaigns/play-2/characters/play-char-b/currency/transfers", map[string]any{"to_character_id": "play-char-w", "gold": 8}, map[string]string{"Authorization": playerBAuth}, 201, map[string]any{"from_character_id": "play-char-b", "to_character_id": "play-char-w", "gold": 8, "from_gold": 10, "to_gold": 8, "transfer_id": 4}),
		playTestExactJSON("play-shop-after-rejected-buy", "Rejected buys leave stock stable", "GET", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"shop_id": "shop-lionshield", "name": "Lionshield Coster", "stock": map[string]any{"healing-potion": 2}, "buy_price": 2, "sell_price": 1}),
		playTest("play-shop-sell-dm-forbidden", "DM cannot sell to shops", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/sell", map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": dmAuth}, 403, nil),
		playTest("play-shop-sell-non-owner-forbidden", "Players cannot sell for another player's character", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/sell", map[string]any{"character_id": "play-char-b", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-shop-sell-invalid-quantity", "Selling validates quantity", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/sell", map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 0}, map[string]string{"Authorization": playerAAuth}, 400, nil),
		playTestExactJSON("play-shop-sell-potion", "Player sells an owned item back to the shop", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/sell", map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 1}, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 1, "gold": 9, "stock": 3}),
		playTest("play-shop-sell-insufficient-inventory", "Selling more than held rejects without mutation", "POST", "/v1/play/campaigns/play-2/settlements/settle-phandalin-shops/shops/shop-lionshield/sell", map[string]any{"character_id": "play-char-w", "item_id": "healing-potion", "quantity": 99}, map[string]string{"Authorization": playerAAuth}, 409, nil),
	)}
}
